PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "Company" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "peopleVineId" TEXT,
    "active" BOOLEAN NOT NULL DEFAULT true,
    "name" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL
, "membershipType" TEXT, "isPersonal" BOOLEAN NOT NULL DEFAULT false, "membershipTypes" TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS "User" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "peopleVineId" TEXT,
    "active" BOOLEAN NOT NULL DEFAULT true,
    "name" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "passwordHashed" TEXT,
    "role" TEXT NOT NULL,
    "companyId" TEXT NOT NULL,
    "emailVerified" BOOLEAN NOT NULL DEFAULT false,
    "mustResetPassword" BOOLEAN NOT NULL DEFAULT false,
    "lastLogin" DATETIME,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL, "primaryMembership" TEXT, "profilePhoto" TEXT, "username" TEXT, "phone" TEXT, "address" TEXT, "city" TEXT, "state" TEXT, "zipCode" TEXT, "cardStatus" TEXT, "memberSource" TEXT NOT NULL DEFAULT 'subscription', "addOns" TEXT NOT NULL DEFAULT '[]', memberSourceCompany TEXT, "primaryMembershipStatus" TEXT,
    CONSTRAINT "User_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE TABLE IF NOT EXISTS "Subscription" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "peopleVineId" TEXT NOT NULL,
    "pvCustomerId" TEXT NOT NULL,
    "companyId" TEXT,
    "title" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "currency" TEXT,
    "rate" REAL,
    "frequency" TEXT,
    "pricing" TEXT,
    "lastDate" DATETIME,
    "nextDate" DATETIME,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL, "customerName" TEXT,
    CONSTRAINT "Subscription_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
